CREATE    PROCEDURE [bud].[jsGetBudgetSummary]      @userId         INT,      @budgetCategory VARCHAR(100),      @subBudget      VARCHAR(124),      @month          VARCHAR(20),      @company        INT  AS  BEGIN      SET NOCOUNT ON;        DECLARE          @totalBudget    DECIMAL(18,2) = 0,          @approvedAmount DECIMAL(18,2) = 0,          @rejectedAmount DECIMAL(18,2) = 0,          @pendingAmount  DECIMAL(18,2) = 0,          @companyTwo     VARCHAR(20),          @monthDate      DATE,          @monthPart      INT,          @yearPart       INT,          @normBudget     VARCHAR(100),          @normSubBudget  VARCHAR(124),          @inputMonth     VARCHAR(20),          @monthMMYYYY    VARCHAR(20),          @monthYYYYMM    VARCHAR(20);        SET @companyTwo = CASE WHEN @company = 1 THEN 'OIL' ELSE 'BEVERAGES' END;        SET @normBudget = LTRIM(RTRIM(COALESCE(@budgetCategory, '')));      SET @normSubBudget = LTRIM(RTRIM(COALESCE(@subBudget, '')));      SET @inputMonth = LTRIM(RTRIM(COALESCE(@month, '')));        SET @monthPart = TRY_CAST(LEFT(@inputMonth, 2) AS INT);      SET @yearPart = TRY_CAST(RIGHT(@inputMonth, 4) AS INT);        IF (          @monthPart IS NULL OR @monthPart NOT BETWEEN 1 AND 12          OR @yearPart IS NULL OR @yearPart NOT BETWEEN 1900 AND 9999      )      BEGIN          SET @monthPart = TRY_CAST(RIGHT(@inputMonth, 2) AS INT);          SET @yearPart = TRY_CAST(LEFT(@inputMonth, 4) AS INT);      END;        SET @monthDate =          CASE              WHEN @monthPart BETWEEN 1 AND 12               AND @yearPart BETWEEN 1900 AND 9999              THEN DATEFROMPARTS(@yearPart, @monthPart, 1)              ELSE NULL          END;        IF @monthDate IS NOT NULL      BEGIN          SET @monthMMYYYY =              RIGHT('0' + CAST(MONTH(@monthDate) AS VARCHAR(2)), 2)              + '-'              + CAST(YEAR(@monthDate) AS VARCHAR(4));            SET @monthYYYYMM =              CAST(YEAR(@monthDate) AS VARCHAR(4))              + '-'              + RIGHT('0' + CAST(MONTH(@monthDate) AS VARCHAR(2)), 2);      END      ELSE      BEGIN          SET @monthMMYYYY = @inputMonth;          SET @monthYYYYMM = @inputMonth;      END;        /*          TOTAL BUDGET PRIORITY:          1. Auth2 allocation tables          2. jsBudgetTable.Current_month_Budget latest non-zero snapshot          3. jsBudgetCategoryMonthSummary legacy fallback      */        IF @monthDate IS NOT NULL      BEGIN          IF @normSubBudget = ''          BEGIN              SELECT                  @totalBudget = COALESCE(SUM(bma.allocatedAmount), 0)              FROM bud.Budgets b              INNER JOIN bud.BudgetMonthlyAllocations bma                  ON bma.budgetId = b.budgetId                 AND bma.allocationMonth = @monthDate              WHERE LTRIM(RTRIM(b.budgetName)) = @normBudget                AND b.company = @company;          END          ELSE          BEGIN              SELECT                  @totalBudget = COALESCE(SUM(sbma.allocatedAmount), 0)              FROM bud.Budgets b              INNER JOIN bud.SubBudgets sb                  ON sb.budgetId = b.budgetId              INNER JOIN bud.SubBudgetMonthlyAllocations sbma                  ON sbma.subBudgetId = sb.subBudgetId                 AND sbma.allocationMonth = @monthDate              WHERE LTRIM(RTRIM(b.budgetName)) = @normBudget                AND b.company = @company                AND LTRIM(RTRIM(COALESCE(sb.subBudgetName, ''))) = @normSubBudget;          END;      END;        IF COALESCE(@totalBudget, 0) = 0      BEGIN          SELECT TOP (1)              @totalBudget = bt.Current_month_Budget          FROM bud.jsBudgetTable bt          WHERE LTRIM(RTRIM(bt.BUDGET)) = @normBudget            AND (                  (@normSubBudget = '' AND (bt.SUB_BUDGET IS NULL OR LTRIM(RTRIM(bt.SUB_BUDGET)) = ''))               OR (@normSubBudget <> '' AND LTRIM(RTRIM(COALESCE(bt.SUB_BUDGET, ''))) = @normSubBudget)            )            AND (                  bt.CURRENTMONTH = @inputMonth               OR bt.CURRENTMONTH = @monthMMYYYY               OR bt.CURRENTMONTH = @monthYYYYMM            )            AND ISNULL(bt.Current_month_Budget, 0) > 0            AND EXISTS (                  SELECT 1                  FROM bud.jsDocEntry jd                  INNER JOIN bud.jsDocEnrtyDetail d                      ON d.docId = jd.id                  WHERE jd.docEntry = bt.DocEntry                    AND d.lineNum = bt.LineNum                    AND d.visOrder = bt.VisOrder                    AND d.company = @companyTwo            )          ORDER BY              COALESCE(bt.UpdateDate, bt.CreatedDate, bt.DocDate, bt.budgetDate) DESC,              bt.DocEntry DESC,              bt.LineNum DESC,              bt.VisOrder DESC;            SET @totalBudget = COALESCE(@totalBudget, 0);      END;        IF COALESCE(@totalBudget, 0) = 0      BEGIN          SELECT              @totalBudget = COALESCE(SUM(s.totalAmount), 0)          FROM bud.jsBudgetCategoryMonthSummary s          WHERE LTRIM(RTRIM(s.budget)) = @normBudget            AND (                  (@normSubBudget = '' AND (s.subBudget IS NULL OR LTRIM(RTRIM(s.subBudget)) = ''))               OR (@normSubBudget <> '' AND LTRIM(RTRIM(COALESCE(s.subBudget, ''))) = @normSubBudget)            )            AND (                  s.[month] = @inputMonth               OR s.[month] = @monthMMYYYY               OR s.[month] = @monthYYYYMM            )            AND s.company = @company;      END;        SET @totalBudget = COALESCE(@totalBudget, 0);        SELECT          @approvedAmount = COALESCE(SUM(b.AMOUNT), 0)      FROM bud.jsBudgetStatusWorkflow wf      INNER JOIN bud.jsDocEnrtyDetail d          ON wf.docId = d.docId      INNER JOIN bud.jsDocEntry jd          ON jd.id = d.docId      INNER JOIN bud.jsBudgetTable b          ON b.DocEntry = jd.docEntry         AND b.LineNum = d.lineNum         AND b.VisOrder = d.visOrder      WHERE wf.userId = @userId        AND wf.status = 'A'        AND LTRIM(RTRIM(b.BUDGET)) = @normBudget        AND (              (@normSubBudget = '' AND (b.SUB_BUDGET IS NULL OR LTRIM(RTRIM(b.SUB_BUDGET)) = ''))           OR (@normSubBudget <> '' AND LTRIM(RTRIM(COALESCE(b.SUB_BUDGET, ''))) = @normSubBudget)        )        AND (              b.CURRENTMONTH = @inputMonth           OR b.CURRENTMONTH = @monthMMYYYY           OR b.CURRENTMONTH = @monthYYYYMM        )        AND d.company = @companyTwo;        SELECT          @rejectedAmount = COALESCE(SUM(b.AMOUNT), 0)      FROM bud.jsBudgetStatusWorkflow wf      INNER JOIN bud.jsDocEnrtyDetail d          ON wf.docId = d.docId      INNER JOIN bud.jsDocEntry jd          ON jd.id = d.docId      INNER JOIN bud.jsBudgetTable b          ON b.DocEntry = jd.docEntry         AND b.LineNum = d.lineNum         AND b.VisOrder = d.visOrder      WHERE wf.userId = @userId        AND wf.status = 'R'        AND LTRIM(RTRIM(b.BUDGET)) = @normBudget        AND (              (@normSubBudget = '' AND (b.SUB_BUDGET IS NULL OR LTRIM(RTRIM(b.SUB_BUDGET)) = ''))           OR (@normSubBudget <> '' AND LTRIM(RTRIM(COALESCE(b.SUB_BUDGET, ''))) = @normSubBudget)        )        AND (              b.CURRENTMONTH = @inputMonth           OR b.CURRENTMONTH = @monthMMYYYY           OR b.CURRENTMONTH = @monthYYYYMM        )        AND d.company = @companyTwo;        ;WITH PendingDocs AS      (          SELECT              jd.docEntry,              d.objType,              d.company,              d.lineNum,              d.visOrder          FROM bud.jsDocEnrtyDetail d          INNER JOIN bud.jsDocEntry jd              ON jd.id = d.docId          WHERE jd.status = 'P'            AND (                  jd.[date] = @inputMonth               OR jd.[date] = @monthMMYYYY               OR jd.[date] = @monthYYYYMM            )            AND d.company = @companyTwo            EXCEPT            SELECT              jd.docEntry,              d.objType,              d.company,              d.lineNum,              d.visOrder          FROM bud.jsBudgetStatusWorkflow wf          INNER JOIN bud.jsDocEntry jd              ON jd.id = wf.docId          INNER JOIN bud.jsDocEnrtyDetail d              ON d.docId = wf.docId          WHERE wf.userId = @userId            AND wf.status IN ('A', 'R')      )      SELECT          @pendingAmount = COALESCE(SUM(b.AMOUNT), 0)      FROM PendingDocs pd      INNER JOIN bud.jsBudgetTable b          ON b.DocEntry = pd.docEntry         AND b.LineNum = pd.lineNum         AND b.VisOrder = pd.visOrder      WHERE LTRIM(RTRIM(b.BUDGET)) = @normBudget        AND (              (@normSubBudget = '' AND (b.SUB_BUDGET IS NULL OR LTRIM(RTRIM(b.SUB_BUDGET)) = ''))           OR (@normSubBudget <> '' AND LTRIM(RTRIM(COALESCE(b.SUB_BUDGET, ''))) = @normSubBudget)        )        AND (              b.CURRENTMONTH = @inputMonth           OR b.CURRENTMONTH = @monthMMYYYY           OR b.CURRENTMONTH = @monthYYYYMM        );        SELECT          @totalBudget    AS TotalBudget,          @approvedAmount AS ApprovedAmount,          @rejectedAmount AS RejectedAmount,          @pendingAmount  AS PendingAmount;  END;
